#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int packed = 0;

    packed |= (10 << 24);
    packed |= (20 << 16);
    packed |= (30 << 8);
    packed |= 40;

    cout << "Data1: " << ((packed >> 24) & 0xff) << endl;
    cout << "Data2: " << ((packed >> 16) & 0xff) << endl;
    cout << "Data3: " << ((packed >> 8) & 0xff) << endl;
    cout << "Data4: " << (packed & 0xff) << endl;

    return 0;
}

