coding.solution:
#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int packed = 0;

    packed |= (1 << 28);
    packed |= (2 << 24);
    packed |= (3 << 20);
    packed |= (4 << 16);
    packed |= (5 << 12);
    packed |= (6 << 8);
    packed |= (7 << 4);
    packed |= 8;

    cout << ((packed >> 28) & 0xf) << " ";
    cout << ((packed >> 24) & 0xf) << " ";
    cout << ((packed >> 20) & 0xf) << " ";
    cout << ((packed >> 16) & 0xf) << " ";
    cout << ((packed >> 12) & 0xf) << " ";
    cout << ((packed >> 8) & 0xf) << " ";
    cout << ((packed >> 4) & 0xf) << " ";
    cout << (packed & 0xf) << endl;

    return 0;
}
